import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/yfr4')
from lib import *
FVG="Portions de fruits et légumes"
def fv(n): return f"{FVG}§{FVG} par portion : {n}"
FRZ="Instructions de congélation : "
recs=[
R(7905259,"Gratin de pâtes, haricots et piment","Un plat réconfortant d'hiver que vous pouvez préparer avec les ingrédients de votre placard.","2","371 g",
["1 petit oignon, haché","½ poivron rouge, haché","1 gousse d'ail, écrasée","100 g de bœuf haché maigre","1 boîte de 230 g de tomates concassées","2 c. à soupe de concentré de tomate","½ c. à café de piment en poudre","1 pincée de paprika","75 g de pâtes complètes sèches de forme courte, cuites et égouttées","1 boîte de 215 g de haricots rouges, égouttés et rincés","1 c. à soupe de persil frais, haché","25 g de chapelure complète","15 g de parmesan râpé"],
["Mettez l'oignon, le poivron, l'ail et la viande hachée dans une poêle antiadhésive et faites revenir 5 minutes, jusqu'à ce que la viande soit dorée et que les oignons commencent à ramollir. Ajoutez les tomates, le concentré de tomate, le piment en poudre et le paprika dans la poêle, portez à ébullition, couvrez et laissez mijoter 10 minutes.","Pendant ce temps, faites cuire les pâtes selon les instructions de l'emballage.","Incorporez les haricots rouges et le persil aux pâtes et faites chauffer. Transférez dans un plat allant au four. Mélangez la chapelure et le parmesan et saupoudrez-en les pâtes.","Placez le plat sous un gril préchauffé 1 à 2 minutes, jusqu'à ce que le dessus soit doré."],
["Pour une saveur tex-mex, ajoutez 1 c. à café rase de cumin moulu et 1 c. à café rase d'origan séché.","Vous pouvez aussi farcir des moitiés de poivrons avec ce mélange de chili, les garnir de cheddar émietté et faire cuire 20 minutes au four.",fv(3)]),
R(7905699,"Ragoût de bœuf éthiopien","Un ragoût de bœuf épicé, traditionnellement servi avec des galettes injera.","4","477 g",
["2 c. à café d'huile de tournesol","500 g de bœuf à braiser, coupé en cubes","2 oignons, hachés","3 gousses de cardamome","1 c. à café de graines de coriandre","2 clous de girofle entiers","2 c. à café de graines de cumin","2 piments verts, hachés","4 gousses d'ail, émincées","1 c. à café de cannelle moulue","1 c. à café de curcuma moulu","2 poivrons verts, hachés","1 boîte de 400 g de tomates concassées","2 carottes, coupées en gros morceaux","2 pommes de terre (200 g chacune), coupées en morceaux","100 g de lentilles corail","1 litre d'eau"],
["Chauffez l'huile dans une casserole et ajoutez le bœuf et les oignons. Faites cuire 5 minutes en remuant régulièrement, jusqu'à ce qu'ils commencent à dorer.","Ajoutez tous les autres ingrédients, remuez et portez à ébullition. Baissez le feu, couvrez la casserole et laissez cuire doucement 1 h 30 à 2 heures en remuant de temps en temps. Servez le ragoût avec l'injera (voir les conseils du chef)."],
["4 injera préparées avec 150 g de farine de teff, 1 grosse pincée de sel et 180 g d'eau + 2 c. à café d'huile pour la cuisson (recette non incluse dans les informations nutritionnelles)","Vous pouvez utiliser de l'agneau ou du poulet à la place du bœuf.","Si vous n'avez pas de lentilles sèches, une boîte convient très bien : choisissez des lentilles en conserve dans de l'eau sans sel ajouté et ajoutez-les pendant les 30 dernières minutes de cuisson. Les haricots adzuki conviennent bien à la place des lentilles.",FRZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce que le plat soit bien chaud à cœur.",fv(3)]),
R(7908780,"Pain irlandais à l'oignon caramélisé, au poivron rouge et à la courgette","Un pain riche en légumes et pauvre en matières grasses. Idéal à rompre et à partager.","12","161 g",
["4 c. à café d'huile de colza","2 oignons rouges (240 g), finement émincés","2 poivrons rouges (260 g), finement émincés","1 courgette (180 g), coupée en petits dés","4 gousses d'ail, écrasées","15 g de tomates séchées, coupées en petits morceaux","25 g de basilic frais, haché","1 c. à café d'origan séché","2 bonnes pincées de poivre noir","600 g de farine complète","1 c. à café de levure chimique","50 g de cheddar, coupé en petits dés","2 c. à soupe bombées de yaourt à 0 % de matières grasses","500 ml d'eau"],
["Préchauffez le four à 180 °C (th. 4).","Versez 2 c. à café d'huile dans une casserole avec les oignons, puis remuez 3 à 4 minutes. Ajoutez ensuite les poivrons et faites cuire encore 4 à 5 minutes en remuant régulièrement.","Ajoutez la courgette et faites cuire encore 3 à 4 minutes en remuant régulièrement.","Retirez la casserole du feu, laissez refroidir un peu, puis ajoutez les tomates séchées, le basilic, l'origan et le poivre.","Versez le reste de l'huile dans un moule à tarte en métal, ou sur une grande plaque de cuisson.","Dans un grand saladier, mettez la farine, la levure et ¾ du fromage.","Ajoutez le yaourt et incorporez progressivement l'eau.","Incorporez les légumes, mélangez vigoureusement, puis versez la préparation dans le moule. Parsemez du reste du fromage et faites cuire 30 à 35 minutes."],
["Essayez d'autres légumes, comme des poireaux, ou testez d'autres fromages, comme la feta ou le parmesan.",FRZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce que le plat soit bien chaud à cœur.",fv(0)]),
R(7912562,"Sauté de jambon et d'ananas","Un plat pauvre en matières grasses, plein de saveur et prêt rapidement.","4","205 g",
["200 g de steak de jambon (gammon), toute graisse visible et couenne retirées","8 oignons nouveaux, finement émincés","1 poivron rouge, épépiné et émincé","115 g de champignons châtaigne, émincés","1 boîte de 220 g de morceaux d'ananas au jus naturel","1 c. à soupe de vinaigre de cidre","2 c. à soupe de concentré de tomate","225 g de germes de soja","poivre noir fraîchement moulu"],
["Coupez le jambon en fines lanières.","Chauffez un wok antiadhésif. Ajoutez le jambon et faites cuire à feu vif 2 à 3 minutes.","Ajoutez les oignons nouveaux émincés, le poivron et les champignons et faites cuire 1 minute.","Égouttez le jus d'ananas dans un bol et mélangez-le avec le vinaigre et le concentré de tomate.","Ajoutez les morceaux d'ananas et les germes de soja dans le wok et versez la sauce dessus. Mélangez bien et portez à ébullition.","Servez directement à la sortie de la poêle."],
[fv(2)]),
R(7912812,"Maquereau rôti en croûte de coriandre au curry","Des filets de maquereau garnis de curry et de coriandre, rôtis sur un lit de poivrons et d'oignons. Un plat de poisson mémorable et savoureux.","4","281 g",
["2 pressions de spray d'huile","1 oignon rouge, épluché et finement émincé","1 poivron rouge, finement émincé","1 poivron vert, finement émincé","1 poivron jaune, finement émincé","4 filets de maquereau (poids total 400 g)","2 c. à café de pâte de curry","25 g de coriandre, finement hachée","1 citron vert, zeste, jus et quartiers pour servir"],
["Préchauffez le four à 180 °C (th. 4). Vaporisez légèrement une plaque de four d'huile.","Placez les oignons et les poivrons sur la plaque et faites cuire 10 minutes en les remuant à quelques reprises pour une cuisson uniforme.","Pendant ce temps, arrosez le poisson de jus de citron vert et étalez délicatement la pâte de curry sur chaque filet.","Mélangez la coriandre et le zeste de citron vert et pressez sur les filets de maquereau, par-dessus la pâte de curry.","Placez le poisson sur les poivrons et faites cuire encore 12 à 15 minutes, jusqu'à ce que le poisson soit cuit à cœur. Servez avec des quartiers de citron vert."],
["Essayez d'autres poissons pour ce plat, comme le tilapia, le cabillaud, la daurade, l'églefin ou le saumon.","Essayez avec d'autres herbes comme le persil ou l'aneth. Ou utilisez de la moutarde à la place de la pâte de curry.",fv(1)]),
R(7919843,"Strudel aux pommes","De la pâte filo garnie de pommes cuites épicées et de raisins secs blonds. Un dessert léger et parfumé.","6","118 g",
["4 pommes moyennes, non épluchées, évidées et coupées en morceaux (500 g)","2 c. à soupe d'eau","25 g de raisins secs blonds","25 g d'abricots secs, hachés","1 c. à café de cannelle moulue","1 c. à café d'extrait d'amande","1 c. à soupe d'édulcorant en poudre","zeste râpé d'1 orange","3 feuilles de pâte filo","7 pressions de spray d'huile"],
["Préchauffez le four à 180 °C (th. 4).","Mettez les pommes dans une casserole avec l'eau, couvrez, puis laissez mijoter doucement 15 minutes en remuant régulièrement, jusqu'à ce qu'elles soient juste tendres.","Ajoutez les raisins secs, les abricots, la cannelle, l'extrait d'amande et la moitié de l'édulcorant. Mélangez bien et réservez.","Posez une feuille de pâte sur une planche et vaporisez-la de deux pressions d'huile, puis saupoudrez d'un tiers de l'édulcorant restant. Posez une autre feuille de pâte dessus et répétez avec deux autres pressions d'huile et un autre tiers de l'édulcorant. Enfin, répétez avec la dernière feuille de pâte, l'huile et le reste de l'édulcorant.","Étalez la préparation aux pommes sur les trois quarts de la pâte, en laissant libre le quart supérieur, puis parsemez de zeste d'orange.","Repliez la longueur supérieure de pâte sur la préparation aux pommes et enroulez le strudel de façon à recouvrir complètement la garniture. Repliez les bords pour éviter que la garniture ne s'échappe et enroulez à nouveau le strudel, de façon que le pli soit en dessous. Placez sur une plaque de cuisson et vaporisez d'huile.","Faites cuire au four 20 à 25 minutes, jusqu'à ce que la pâte soit légèrement dorée.","Servez avec une cuillerée de yaourt, ou d'une alternative végétale au soja, et une pincée de cannelle."],
["Essayez d'utiliser des poires à la place des pommes, ou ajoutez quelques myrtilles ou mûres."]),
R(7920025,"Salade César au poulet grillé","Une version plus légère de la salade d'été classique, parfaite pour les barbecues.","4","142 g",
["Pour la sauce§20 g de parmesan, finement râpé","Pour la sauce§2 c. à soupe de yaourt allégé","Pour la sauce§1 c. à soupe d'huile d'olive extra vierge","Pour la sauce§1 c. à café de moutarde de Dijon","Pour la sauce§jus d'un quart de citron","Pour la sauce§1 c. à café de sauce Worcestershire","Pour la sauce§1 pincée de poivre blanc","Pour la salade§80 g de laitue « little gem »","Pour la salade§2 blancs de poulet sans peau ni os","Pour la salade§1 c. à café d'huile d'olive","Pour les croûtons§1 gousse d'ail, écrasée","Pour les croûtons§1 c. à café d'huile d'olive","Pour les croûtons§1 pincée de poivre noir","Pour les croûtons§100 g de baguette/ciabatta, coupée en cubes"],
["Préchauffez le four à 180 °C (th. 4). Mélangez tous les ingrédients de la sauce et laissez infuser.","Pour la salade, séparez la laitue en feuilles individuelles, lavez et égouttez soigneusement.","Coupez les blancs de poulet en deux dans l'épaisseur pour les amincir, frottez-les d'un peu d'huile, puis faites-les cuire sur une plaque à griller chaude 2 à 3 minutes de chaque côté, ou jusqu'à ce qu'ils soient bien cuits à cœur. Laissez refroidir légèrement, puis coupez en lanières.","Pour préparer les croûtons, mettez l'ail et l'huile d'olive dans un bol et écrasez-les encore avec le dos d'une cuillère. Ajoutez le poivre noir, mélangez bien et enduisez l'intérieur du bol du mélange.","Ajoutez les cubes de pain et mélangez pour que tout le pain soit enrobé d'un peu d'huile. Étalez les cubes sur une plaque de cuisson et faites cuire dans le four préchauffé environ 8 à 10 minutes, en les retournant à quelques reprises avec une spatule et en veillant à ne pas les brûler.","Pour l'assemblage, disposez la laitue en couches dans un plat creux, en gardant les plus petites feuilles pour la fin afin de former des cercles concentriques. Arrosez de sauce, parsemez de croûtons et de poulet, et terminez avec les copeaux de parmesan."],
["Si vous avez le temps, plongez la laitue dans de l'eau glacée juste avant de l'utiliser, pour raviver et rendre les feuilles croquantes.",fv(0)]),
R(7920525,"Lasagnes aux épinards et aux champignons","Des lasagnes plus pauvres en matières grasses, avec une sauce crémeuse aux épinards et aux champignons, garnies de tomates fraîches.","6","483 g",
["1 boîte de 800 g de tomates concassées","1 c. à soupe de concentré de tomate","2 gousses d'ail, écrasées","1 c. à café bombée d'origan séché","1 c. à café d'huile d'olive","1 oignon, finement haché","1 gros poivron rouge, finement haché","250 g de champignons, finement émincés","2 c. à café de farine ordinaire","250 ml de lait écrémé","300 g d'épinards surgelés (150 g une fois décongelés et égouttés)","100 g de fromage frais extra-léger","1 c. à café de moutarde de Dijon","1 bonne pincée de poivre noir","1 paquet de 250 g de lasagnes complètes","2 à 3 tomates fraîches, finement tranchées","30 g de cheddar","6 feuilles de basilic frais, déchirées, pour la garniture"],
["Préchauffez le four à 180 °C (th. 4). Mixez ensemble les tomates, le concentré de tomate, l'ail et l'origan pour obtenir une sauce tomate, puis réservez.","Chauffez l'huile dans une casserole et ajoutez l'oignon. Faites cuire 2 à 3 minutes, ajoutez le poivron rouge et faites cuire encore 2 à 3 minutes. Ajoutez les champignons, faites cuire 2 minutes, puis incorporez progressivement la farine pour enrober les légumes.","Incorporez progressivement le lait jusqu'à ce que le mélange commence à épaissir, ajoutez les épinards et remuez 1 minute, puis incorporez le fromage frais, la moutarde et le poivre noir.","Versez un peu de sauce tomate dans un plat allant au four, puis recouvrez d'une couche de feuilles de lasagnes. Ajoutez maintenant une couche du mélange de champignons, d'épinards et de fromage frais et répétez jusqu'à terminer par une couche de sauce tomate, puis recouvrez de tranches de tomates finement coupées.","Saupoudrez de cheddar et faites cuire 30 à 35 minutes. Parsemez de basilic frais pour servir."],
["Pour une version sans gluten, ou si vous surveillez votre consommation de glucides, utilisez 3 à 4 aubergines émincées à la place des feuilles de lasagnes et utilisez de la farine sans gluten dans la sauce.",FRZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce que le plat soit bien chaud à cœur.","Servez avec une grande salade de feuilles vertes pour apporter des vitamines et des minéraux supplémentaires et de la fraîcheur au plat.",fv(3)]),
R(7920715,"Soufflé au chocolat et à l'orange","Le cacao en poudre donne à ce dessert un merveilleux goût riche de chocolat.","6","73 g",
["Un peu d'huile végétale, pour graisser","Zeste râpé et jus de 2 grosses oranges","75 g de sucre en poudre","4 gros blancs d'œufs, battus en neige ferme","25 g de cacao en poudre","2 c. à soupe de jus d'orange","Quelques gouttes d'arôme d'orange (en vente dans tous les bons supermarchés)","4 c. à soupe de crème fraîche allégée"],
["Préchauffez le four à 200 °C (chaleur tournante 180 °C, th. 6).","Graissez légèrement 6 tasses à thé allant au four. Dans une petite casserole, faites chauffer le zeste d'orange, le jus et le sucre en poudre 3 à 4 minutes, jusqu'à obtenir un sirop. Versez le sirop sur les blancs d'œufs et battez 2 minutes.","Incorporez délicatement le mélange de cacao et de jus d'orange, puis versez dans les tasses.","Faites cuire au four 5 à 6 minutes, ou jusqu'à ce que les soufflés soient gonflés.","Servez nappé de crème fraîche."],
["Si vous avez du mal à faire monter correctement vos blancs d'œufs, ajoutez une ou deux gouttes de jus de citron pour aider à renforcer la structure de la préparation.","Pour que vos soufflés gonflent, ne mélangez pas trop. Incorporez plutôt délicatement les blancs jusqu'à ce que les traînées blanches disparaissent.","Utilisez des œufs frais, à température ambiante. Fouetter des œufs froids demande plus d'efforts et ils ne gonflent pas autant."]),
R(7923594,"Pyaaj pakora, oignons en pâte à frire cuits au four","Une délicieuse alternative plus saine aux pakoras frits.","12","37 g",
["20 pressions de spray de cuisson allégé","8 c. à soupe de farine de pois chiches","4 c. à soupe de farine de riz","1/2 c. à café de curcuma moulu","1/2 c. à café de graines d'ajowan","1/2 c. à café de coriandre moulue","1/2 c. à café de piment en poudre","2 petits oignons (250 g), émincés"],
["Préchauffez le four à 200 °C (chaleur tournante 180 °C, th. 6). Chemisez quelques plaques de cuisson de papier sulfurisé et vaporisez 10 à 12 endroits régulièrement espacés d'huile.","Tamisez la farine de pois chiches et la farine de riz dans un saladier. Ajoutez le curcuma, les graines d'ajowan, la coriandre moulue et le piment en poudre.","Ajoutez 6 cuillères à soupe d'eau froide et mélangez bien, en transformant les farines épicées en une pâte épaisse et en écrasant les grumeaux éventuels.","Ajoutez les oignons à la pâte et mélangez-les pendant quelques minutes pour les enrober complètement. Ils ramollissent aussi légèrement, car ils libèrent de l'humidité lorsqu'on les remue.","À l'aide de deux cuillères à soupe, déposez des quantités égales d'oignons enrobés de pâte sur les endroits huilés des plaques de cuisson. Ramenez les morceaux d'oignon égarés près du monticule pour éviter d'avoir trop de bords brûlés.","Lorsque tous les oignons sont utilisés, vaporisez chaque monticule d'un peu plus d'huile et enfournez 20 minutes. Sortez du four, retournez les pakoras et faites cuire encore 10 minutes. Laissez reposer 5 minutes avant de vous régaler."],
["Veillez à ce que les oignons soient très finement émincés afin qu'ils sortent bien cuits du four.","Extrait de Masala de Mallika Basu, photographies © Issy Croker"]),
R(7924662,"Salade de chèvre, betterave et noix","Une salade légère et facile à préparer, parfaite pour les fêtes et les barbecues.","2","200 g",
["3 à 4 betteraves crues selon leur taille (environ 250 g)","2 c. à café d'huile d'olive","1 sachet de 60 g de roquette","50 g de fromage de chèvre","1 c. à soupe bombée de noix","jus d'un demi-citron","poivre noir fraîchement moulu"],
["Préchauffez le four à 200 °C (th. 6). Lavez les betteraves, coupez-en les deux extrémités, puis coupez-les en quatre (inutile de les éplucher). Mélangez la betterave avec l'huile d'olive, étalez sur une plaque de cuisson et faites cuire au four 25 minutes. Laissez refroidir, retirez la peau, coupez en morceaux et réservez.","Pendant ce temps, disposez les feuilles de roquette sur un grand plat.","Placez les morceaux de betterave dessus et émiettez uniformément le fromage de chèvre sur la salade. Parsemez ensuite de noix.","Enfin, arrosez de jus de citron. Poivrez. (Faites cette dernière étape juste avant de servir ; tout le reste peut être préparé à l'avance.)"],
["Pour réduire la quantité de matières grasses de cette recette, ajoutez plus de betterave et de feuilles de roquette, et diminuez la quantité de noix.","Cette recette convient aussi très bien avec des morceaux de carottes ou de courge butternut rôties.",fv(1)]),
R(7926248,"Tortilla espagnole copieuse","Une recette savoureuse et facile à laquelle vous pouvez ajouter d'autres ingrédients comme du bacon ou du jambon. Délicieuse chaude, tiède ou froide. Un excellent plat de pique-nique.","2","372 g",
["425 g de pommes de terre, épluchées et coupées en tranches","1 c. à café d'huile","1 oignon rouge, émincé","½ poivron vert, finement émincé","1 c. à soupe de persil frais, haché","3 œufs, battus","1 c. à soupe de parmesan râpé","poivre noir fraîchement moulu"],
["Faites cuire les pommes de terre dans de l'eau bouillante 5 à 6 minutes, jusqu'à ce qu'elles soient juste tendres. Égouttez.","Chauffez l'huile dans une petite poêle, ajoutez l'oignon et le poivron et faites revenir 3 à 4 minutes, jusqu'à ce qu'ils soient ramollis.","Ajoutez les pommes de terre et le persil et mélangez délicatement. Battez ensemble les œufs et le parmesan et assaisonnez.","Préchauffez le gril. Versez le mélange d'œufs dans la poêle et faites cuire 3 minutes. Placez sous le gril et faites cuire jusqu'à ce que le dessus soit doré et pris.","Servez avec une salade croquante."],
["Vous pouvez ajouter toutes sortes d'ingrédients pour plus de saveur : un champignon finement haché, du bacon fumé ou du jambon. Essayez d'ajouter de l'ail écrasé ou des épinards cuits et hachés.","Pour une version végétarienne, utilisez une alternative au parmesan, ou essayez avec du fromage de chèvre ou du cheddar affiné.",fv(1)]),
R(7931899,"Gâteau d'avoine aux fruits","Une collation rassasiante, riche en fibres, délicieuse avec une tasse de thé et excellente à tremper. Envoyée par Philip Robinson","12","40 g",
["100 g de matière grasse tartinable allégée","125 g de flocons d'avoine","120 g de farine complète","75 g de pruneaux dénoyautés, hachés","65 g de raisins secs blonds","1 c. à café de mélange d'épices (mixed spice)","1 c. à café de gingembre","2 petits œufs, battus","1 à 2 c. à café d'édulcorant en poudre"],
["Préchauffez le four à 180 °C (th. 4). Faites fondre la matière grasse dans une casserole à feu doux et réservez, en gardant 2 c. à café pour graisser le plat de cuisson.","Mettez les flocons d'avoine et la farine dans un bol et mélangez. Ajoutez les pruneaux, les raisins secs, le mélange d'épices et le gingembre. Mélangez bien.","Ajoutez la matière grasse fondue et mélangez. Ajoutez les œufs battus et 100 ml d'eau. Mélangez bien.","Graissez un moule de 20 cm x 26 cm, versez-y la préparation et tassez doucement sur environ 1 cm d'épaisseur.","Saupoudrez légèrement d'édulcorant et faites cuire 20 à 25 minutes.","Laissez refroidir avant de couper en 12 morceaux et de servir."],
["Utilisez un presse-purée pour tasser uniformément la préparation dans le moule.","Essayez d'autres fruits secs, comme des abricots hachés ou des raisins secs.","Pour une version plus pauvre en matières grasses, remplacez 50 g de matière grasse allégée par une banane bien écrasée.",fv(0)]),
]
save(6,recs)
